package net.civeira.phylax.feature.observe.observedslo.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.valueobject.LatencyMsVO;

class LatencyMsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of latency ms of observed slo")
  void test_latency_ms_value_holder_assign_plain_value() {
    Object holder = new Object();
    LatencyMsValueHolder<Object> value = new LatencyMsValueHolder<>(holder);
    Assertions.assertSame(holder, value.latencyMs(1), "Setters must return the holder");
    Assertions.assertTrue(value.getLatencyMsValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getLatencyMs().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.latencyMsNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLatencyMsValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLatencyMs().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of latency ms of observed slo")
  void test_latency_ms_value_holder_assign_value_object() {
    Object holder = new Object();
    LatencyMsValueHolder<Object> value = new LatencyMsValueHolder<>(holder);
    LatencyMsVO vo = LatencyMsVO.from(1);
    Assertions.assertFalse(value.getLatencyMsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.latencyMs(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLatencyMsValue().orElseThrow());
    Assertions.assertSame(holder, value.latencyMs(Optional.empty()));
    Assertions.assertFalse(value.getLatencyMsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.latencyMs(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLatencyMsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of latency ms of observed slo against the original")
  void test_latency_ms_value_holder_read() {
    Object holder = new Object();
    LatencyMsValueHolder<Object> value = new LatencyMsValueHolder<>(holder);
    LatencyMsVO vo = LatencyMsVO.from(1);
    LatencyMsVO other = LatencyMsVO.from(1);
    ObservedSlo original = Mockito.mock(ObservedSlo.class);
    Mockito.when(original.getLatencyMsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLatencyMs(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLatencyMs(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.latencyMs(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLatencyMs(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLatencyMs(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of latency ms of observed slo")
  void test_latency_ms_value_holder_unset() {
    Object holder = new Object();
    LatencyMsValueHolder<Object> value = new LatencyMsValueHolder<>(holder);
    LatencyMsVO vo = LatencyMsVO.from(1);
    value.latencyMs(vo);
    Assertions.assertSame(holder, value.unsetLatencyMsIfMatches("latencyMs_other"));
    Assertions.assertTrue(value.getLatencyMsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLatencyMsIfMatches("latencyMs"));
    Assertions.assertFalse(value.getLatencyMsValue().isPresent(),
        "The field name must clear the value");
    value.latencyMs(vo);
    Assertions.assertSame(holder, value.unsetLatencyMs());
    Assertions.assertFalse(value.getLatencyMsValue().isPresent(), "Unset must clear the value");
  }
}
